INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (19, 3, 'theory', 'Квиз: systemd');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 3, 0, 'В app.service написано Requires=db.service и After=db.service. Служба db.service не смогла запуститься. Что будет с app.service?', '["Запустится как обычно: Requires не проверяет результат", "Запустится позже, после повторной попытки db.service", "Не будет запущена, потому что требуемый юнит не стартовал, а порядок задан", "Систем-ди перезагрузит сервер"]', 2, 'Если требуемый юнит не запустился и на него задан порядок After, зависящий юнит запускаться не будет. Без After он стартовал бы параллельно и результата db не ждал. Wants вместо Requires отказ db бы просто пережил.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 3, 1, 'Как правильно заменить команду запуска службы в drop-in, а не добавить вторую?', '["Написать ExecStart= с пустым значением, а затем новый ExecStart=", "Написать ещё одну строку ExecStart= с новой командой", "Отредактировать файл в /usr/lib/systemd/system напрямую", "Написать ExecStart=none"]', 0, 'ExecStart — списочная настройка: пустое присваивание сбрасывает накопленный список. Простая вторая строка даст у обычной службы две команды, а это допустимо только для oneshot, и юнит не загрузится.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 3, 2, 'Что делает Persistent=true в таймере с OnCalendar?', '["Не даёт таймеру отключиться при перезагрузке", "Запускает службу каждую минуту", "Запрещает запускать службу вручную", "Запоминает время последнего запуска и догоняет пропущенный запуск при включении"]', 3, 'Persistent хранит время последнего срабатывания на диске. Если в расписанное время машина была выключена, пропущенный запуск выполнится сразу после старта. Работает только с OnCalendar.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 3, 3, 'Служба с Restart=on-failure завершилась с кодом выхода 0. Что сделает систем-ди?', '["Перезапустит её, как после любого выхода", "Не станет перезапускать: чистый выход не считается отказом", "Пометит юнит как failed и перезапустит через минуту", "Перезапустит, но только после ручного reset-failed"]', 1, 'on-failure реагирует на ненулевой код, аварийный сигнал, таймаут и сторожевой таймер. Код 0 — чистый выход, перезапускает такую службу только политика always (и on-success).');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 3, 4, 'Что означает число после плюса в строке systemd-analyze critical-chain?', '["Момент, когда юнит был остановлен", "Сколько памяти занял юнит", "Сколько времени юнит запускался", "Сколько раз юнит перезапускался"]', 2, 'После @ стоит время, когда юнит стал активным или начал запуск, а после + — сколько занял запуск юнита. Память и счётчик рестартов эта команда не показывает.');
